What does the following program print?

int a = 2, b = 3, c = 4;
int r = a + b * c - c / a % 3;
printf("%d", r);

What does the following program print?

int a = 0, b = 5, c, d, e;
c = (a++ && b++);
d = (a++ || b++);
e = (a-- && b++);
printf("%d", a * 10000 + b * 1000 + c * 100 + d * 10 + e);

What does the following program print?

int a = 17, b = 5, q = 0;
while (a >= b) { a -= b; q++; }
printf("%d", q * 10 + a);
